return [{json:(function settingsForRun(settings) {
  const match = settings.categories.find(c => c.label === settings.category);
  const query = String(settings.customQuery || match?.query || '').trim();
  if (!query || !settings.districts.includes(settings.district)) throw new Error('Ayarlar düğümünde bir sağlık kategorisi ve geçerli Antalya ilçesi seçin.');
  if (!['pilot','places'].includes(settings.mode)) throw new Error('mode değeri pilot veya places olmalı.');
  return {...settings,query};
})(settings)}];

const cfg=$input.first().json;
const dental=settings=>(function previewBatch(config, samples) {
  const results = samples.filter(row => row[0] === config.district).map(([,name,address,source,websiteFinding,officialMap,mapType]) => ({
    name, address, source, websiteFinding, traffic:'Ölçülemedi',
    mapUrl:officialMap || 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(name + ' ' + address),
    mapType:mapType || 'Adresle haritada ara',
    draft:name === 'Özel VDC' ? 'Merhaba VDC ekibi, sitenizde randevu formunun WhatsApp’ta hazır bir mesaj açtığını gördüm. Form doldurma sayısıyla gelen randevu taleplerini karşılaştırmaya yönelik kısa bir ölçüm önerim var. 15 dakikalık bir görüşme için uygun olduğunuz bir zaman var mı?' : '',
  }));
  const index = config.districts.indexOf(config.district);
  return { mode:'pilot', city:config.city, district:config.district, nextDistrict:index < 0 ? null : config.districts[index+1] || null, results };
})(settings,[["Muratpaşa","Özel VDC","Bahçelievler Mah. Piri Reis Cd. No:18A, Muratpaşa/Antalya","https://vdcdis.com.tr/iletisim/","Randevu formu, gönderilecek mesajı WhatsApp’ta açıyor.","https://www.google.com/maps/dir/?api=1&destination=36.886992%2C30.68307","Kliniğin yayımladığı yol tarifi"],["Muratpaşa","ED Klinik","Yeşilbahçe Mah. Metin Kasapoğlu Cd. Beytaş Sitesi A Blok No:2/3, Muratpaşa/Antalya","https://edklinik.com/iletisim","İletişim sayfasında telefon, WhatsApp ve randevu bağlantısı var.","https://maps.google.com/?cid=9321649780581538669","Kliniğin yayımladığı harita kaydı"],["Muratpaşa","Egedent Antalya","Meydankavağı Mah. İsmail Cem Cad. No:43/A, Muratpaşa/Antalya","https://www.egedentantalya.com/iletisim/","İletişim sayfasında randevu talep formu var."],["Konyaaltı","Dentology","Pınarbaşı Mah. Pınarbaşı Cad. No:8/A, Konyaaltı/Antalya","https://dentologyantalya.com/iletisim/","İletişim sayfası online saat seçimi ve form seçenekleri sunuyor.","https://maps.app.goo.gl/QQg1R3BpzQjAjPHg7","Kliniğin yayımladığı harita kaydı"],["Kepez","Ahenk Diş","Yeni Doğan Mah. Şht. Uz. Çvş. Ali Yılmaz Cd. No:57/A, Kepez/Antalya","https://www.ahenkdis.com/iletisim/","İletişim sayfası telefonla randevu bağlantısı sunuyor."]]);
return [{json:(function demoData(cfg, dentalPreview, extra) {
  const base = cfg.category === 'Diş klinikleri' && !cfg.customQuery ?
    dentalPreview(cfg).results.map(row=>({...row,website:row.source.match(/^https?:\/\/[^/]+/)?.[0]+'/'})) : [];
  if (cfg.district === 'Muratpaşa' && !cfg.customQuery) {
    for (const row of extra.filter(row=>row.categories.includes(cfg.category))) {
      base.push({name:row.name,address:row.address,source:row.source,website:row.website,websiteFinding:row.finding,
        traffic:'Ölçülemedi',mapUrl:'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(row.name+' '+row.address),mapType:'Adresle haritada ara'});
    }
  }
  return {mode:'pilot',city:cfg.city,district:cfg.district,results:base};
})(cfg,dental,[{"categories":["Saç ekimi"],"name":"BT Hair Clinic Antalya","address":"Kışla Mah., Güllük Cd., Selekler Çarşısı No:2/110, Muratpaşa/Antalya","website":"https://bthairclinicantalya.com/","source":"https://bthairclinicantalya.com/iletisim/","finding":"İşletmenin iletişim sayfasında Antalya adresi ve saç ekimi hizmeti yer alıyor."},{"categories":["Estetik doktorları","Burun estetiği"],"name":"Op. Dr. Harun Şimşek","address":"Fener Mah., Tekelioğlu Cd., Kayıkent Sitesi B Blok No:33/A, Muratpaşa/Antalya","website":"https://harunsimsek.com.tr/","source":"https://harunsimsek.com.tr/tr/iletisim","finding":"Hekimin iletişim sayfasında Muratpaşa adresi ve burun estetiği çalışma alanı yer alıyor."},{"categories":["Estetik doktorları","Burun estetiği","Annelik estetiği"],"name":"Op. Dr. Mustafa Keleş","address":"Tarım Mah., Perge Bulvarı, Muratpaşa/Antalya","website":"https://www.drmustafakeles.com/","source":"https://www.drmustafakeles.com/","finding":"Hekimin web sitesinde burun ve annelik estetiği için ayrı hizmet sayfaları var."}])}];

return [{json:(function placesBatch(config, pages) {
  const fold = s => String(s || '').toLocaleLowerCase('tr-TR').normalize('NFD').replace(/\p{M}/gu, '').replaceAll('ı','i');
  const district = fold(config.district);
  const province = fold(config.city);
  const seen = new Set();
  const results = [];
  for (const item of pages) {
    const page = item.json.body || item.json;
    for (const place of page.places || []) {
      const tokens = fold(place.formattedAddress).split(/[^a-z0-9]+/);
      const components = (place.addressComponents || []).map(c => fold(c.longText));
      const name = place.displayName?.text;
      if (!name || !place.id || seen.has(place.id) ||
        (place.businessStatus && place.businessStatus !== 'OPERATIONAL') ||
        (!tokens.includes(district) && !components.includes(district)) ||
        (!tokens.includes(province) && !components.includes(province))) continue;
      seen.add(place.id);
      results.push({
        name, address:place.formattedAddress || '', placeId:place.id,
        mapUrl:place.googleMapsUri || 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(name) + '&query_place_id=' + encodeURIComponent(place.id),
        mapType:'Google Haritalar işletme kaydı',
        source:place.websiteUri || '',
        websiteFinding:place.websiteUri ? 'Haritalar kaydında web sitesi bağlantısı var.' : 'Bu Haritalar kaydında web sitesi bağlantısı bulunamadı.',
        traffic:'Ölçülemedi',
      });
    }
  }
  const last = pages.at(-1)?.json;
  const index = config.districts.indexOf(config.district);
  return { mode:'places', city:config.city, district:config.district, nextDistrict:index < 0 ? null : config.districts[index+1] || null, morePages:Boolean((last?.body || last)?.nextPageToken), results };
})( $('Ayarlar').first().json,$input.all())}];

const cfg=$('Ayarlar').first().json;
const report=(function report(batch,cfg) {
  const websiteLink = result => {
    const candidate = result.website || (batch.mode === 'places' ? result.source : '');
    return /^https?:\/\/[^\s]+$/i.test(candidate || '') ? candidate : null;
  };
  const thirdParty = link => /(^|\.)(facebook\.com|instagram\.com|wa\.me|whatsapp\.com|linktr\.ee|doktorsitesi\.com|doktortakvimi\.com)$/i.test(link?.match(/^https?:\/\/([^/?:#]+)/i)?.[1] || '');
  const records = batch.results.map(result=>{
    const link = websiteLink(result);
    const externalProfile = thirdParty(link) ? link : null;
    const website = externalProfile ? null : link;
    const status = batch.mode === 'places'
      ? website ? 'Haritalar kaydında site bağlantısı var' : externalProfile ? 'Haritalar kaydında profil veya rehber bağlantısı var' : 'Haritalar kaydında site bağlantısı yok'
      : 'Web sitesi işletmenin kendi sayfasından doğrulandı';
    return {...result, website, externalProfile, websiteStatus:status,seoScore:null,seoStatus:website?'SEO kontrolü bekliyor':'Site adresi bekleniyor'};
  });
  const siteCandidates = records.filter(r=>r.website);
  const externalProfiles = records.filter(r=>r.externalProfile);
  const noWebsiteOnMaps = batch.mode === 'places' ? records.filter(r=>!r.website&&!r.externalProfile) : [];
  return {...batch,category:cfg.category,query:cfg.query,results:records,counts:{total:records.length,withoutMapsWebsite:noWebsiteOnMaps.length,withWebsite:siteCandidates.length},
    noWebsiteOnMaps, externalProfiles, siteCandidates:siteCandidates.map(r=>({business:r.name,url:r.website,address:r.address,mapUrl:r.mapUrl})),
    seoUrls:[...new Set(siteCandidates.map(r=>r.website))],
  };
})($input.first().json,cfg);
return [{json:{...report,html:(function render(report,key) {
  const esc = (s) => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
  const link = (url,label) => /^https?:\/\/[^\s]+$/i.test(url||'') ? '<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+esc(label)+'</a>' : '';
  const section = (title,records) => '<section><h2>'+esc(title)+'</h2>'+ (records.length ? records.map((r,i)=>{
    const query = r.placeId ? 'place_id:'+r.placeId : r.name+' '+r.address;
    const map = key && /^[A-Za-z0-9_-]+$/.test(key) ?
      '<iframe title="'+esc(r.name)+' haritası" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" src="https://www.google.com/maps/embed/v1/place?key='+encodeURIComponent(key)+'&amp;q='+encodeURIComponent(query)+'"></iframe>' : '';
    return '<details '+(i===0?'open':'')+'><summary>'+esc(r.name)+'</summary><p>'+esc(r.address)+'</p><p>'+
      link(r.mapUrl,r.mapType)+' '+link(r.website,'Siteyi aç')+' '+link(r.source,'Kaynak')+'</p>'+map+'<p>'+
      esc(r.websiteStatus)+'</p>'+(r.draft?'<p><strong>Teklif taslağı</strong></p><p>'+esc(r.draft)+'</p>':'')+'</details>';
  }).join(''):'<p>Bu grupta kayıt görünmüyor.</p>')+'</section>';
  const title=report.city+' · '+report.district+' · '+report.category;
  const note=report.mode==='pilot'?'Önizleme · İşletmelerin kendi sayfalarından hazırlanmış örnekler.':'Kaynak · Google Maps';
  return '<!doctype html><html lang="tr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+
    '</title><style>body{font:16px/1.5 system-ui;color:#173329;background:#f4f7f3;max-width:960px;margin:28px auto;padding:0 16px}section{margin-block:24px}details{background:white;border:1px solid #c9d9ce;border-radius:10px;padding:16px;margin:10px 0}summary{font-weight:650;cursor:pointer}a{color:#176047;margin-right:12px}iframe{width:100%;height:320px;border:0}</style><h1>'+
    esc(title)+'</h1><p>'+esc(note)+'</p>'+
    (report.mode==='places'?section('Haritalar kaydında site bağlantısı yok',report.noWebsiteOnMaps):'')+
    (report.externalProfiles.length?section('Profil veya rehber bağlantıları',report.externalProfiles):'')+
    section('SEO kontrolüne uygun site adresleri',report.results.filter(r=>r.website))+'</html>';
})(report,cfg.mapsEmbedKey)}}];
